}","new_string":"/**
 * Parse INI text into its settings.
 * @param {string} text - the file's whole text.
 * @returns {Map<string, {text: string, line: number, column: number}>} each dotted key's raw value and position, in the order the file writes them.
 * @throws {IniError} on the first line the grammar refuses.
 */
export function parse(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const values = new Map()
  let currentSection = ''

  for (const [index, raw] of lines.entries()) {
    const line = index + 1
    const trimmed = raw.trim()

    // Ignore empty lines and comments
    if (trimmed === '' || trimmed.startsWith('#') || trimmed.startsWith(';')) continue

    // Check for section header
    if (trimmed.startsWith('[')) {
      if (!trimmed.endsWith(']')) {
        throw new IniError(line, raw.trimEnd().length + 1, 'expected "]"')
      }

      const sectionName = trimmed.slice(1, -1)
      if (sectionName === '') {
        throw new IniError(line, indent(raw), 'expected a section name')
      }

      if (!NAME.test(sectionName)) {
        throw new IniError(line, indent(raw), `invalid section name ${sectionName}`)
      }

      currentSection = sectionName
      continue
    }

    // Parse key = value
    const eqIndex = trimmed.indexOf('=')
    if (eqIndex === -1) {
      throw new IniError(line, indent(raw), 'expected a section header or key = value')
    }

    const keyPart = trimmed.slice(0, eqIndex).trim()
    if (keyPart === '') {
      throw new IniError(line, indent(raw) + eqIndex, 'expected a key')
    }

    if (!NAME.test(keyPart)) {
      throw new IniError(line, indent(raw), `invalid key ${keyPart}`)
    }

    const key = currentSection ? `${currentSection}.${keyPart}` : keyPart

    // Check for duplicate key
    if (values.has(key)) {
      throw new IniError(line, indent(raw), `key ${key} is set twice`)
    }

    // Parse value
    const valuePart = trimmed.slice(eqIndex + 1)

    // Calculate column position for the value
    const after = indent(raw) + eqIndex
    const rest = raw.slice(after)
    let column
    if (rest.trim() === '') {
      // One past the last non-space character
      column = raw.trimEnd().length + 1
    } else {
      // First non-space character of the value
      column = after + (rest.length - rest.trimStart().length) + 1
    }

    values.set(key, { text: valuePart.trim(), line, column })
  }

  return values
}"}

